"""Bundled private watch UI; no external resources or browser storage."""

import html

# Native HTML/CSS/JS line lengths remain readable.
# ruff: noqa: E501


def render_page(nonce, *, session_management=False):
    page = PAGE.replace("@@NONCE@@", html.escape(nonce, quote=True))
    if session_management:
        page = page.replace(
            "</header>",
            '<a href="/session" class="pill">Device sign-in</a></header>',
            1,
        )
        page = page.replace(
            "</head>",
            '<link rel="manifest" href="/manifest.webmanifest"><link rel="apple-touch-icon" href="/session/icon.png"></head>',
            1,
        )
    return page


PAGE = r"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>Sniper · Your watches</title>
<style nonce="@@NONCE@@">
:root{color-scheme:dark;--bg:#101827;--panel:#182337;--line:#364761;--muted:#b6c4d8;--accent:#b7f2cf;--ink:#eef3ff}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 system-ui,sans-serif}main{max-width:1180px;padding:36px 24px 64px;margin:auto}header{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:36px}.accent{color:var(--accent)}.form-actions{margin-top:20px}.brand{font-size:19px;letter-spacing:3px;font-weight:850}.pill{font-size:12px;border:1px solid var(--line);padding:7px 12px;border-radius:30px;color:var(--muted)}h1{font-size:clamp(32px,5vw,52px);letter-spacing:-2px;line-height:1.1;margin:0 0 14px}h2{font-size:21px;margin:0 0 12px}h3{margin:0;font-size:19px}p{margin:0 0 14px}.muted,small{color:var(--muted)}.intro{max-width:720px}.layout{display:grid;grid-template-columns:360px minmax(0,1fr);gap:24px;align-items:start;margin-top:24px}.panel,.card{border:1px solid var(--line);border-radius:16px;background:var(--panel);padding:22px}.panel{position:sticky;top:20px}label{display:block;margin:16px 0;font-weight:650;font-size:14px}input,select,button{font:inherit;border:1px solid #52634b;border-radius:9px;min-height:46px}input,select{display:block;width:100%;padding:11px;background:var(--bg);color:var(--ink);margin:6px 0}button{cursor:pointer;padding:10px 16px;background:var(--accent);color:#15200b;font-weight:750}button.secondary{color:var(--ink);background:transparent;border-color:var(--line)}button:disabled{opacity:.45;cursor:not-allowed}input:focus,select:focus,button:focus-visible,a:focus-visible{outline:3px solid var(--accent);outline-offset:3px}small{display:block;font-size:12px;font-weight:400;margin-top:6px}.row{display:flex;gap:12px}.row>*{flex:1;min-width:0}.check{display:flex;align-items:center;gap:10px}.check input{width:19px;min-height:19px;flex:none}.full{width:100%}.toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:14px}.toolbar h2{margin:0}.cards{display:grid;gap:14px}.card p{font-size:14px;margin:8px 0}.card-top{display:flex;justify-content:space-between;gap:12px;align-items:start}.price{font-size:23px;font-weight:750;letter-spacing:-.6px}.card a{color:var(--accent)}.card-actions{display:flex;gap:10px;margin-top:15px}.card-actions button{font-size:14px}.meta{display:grid;grid-template-columns:1fr 1fr;gap:12px;border-top:1px solid var(--line);padding-top:12px;margin-top:14px}.meta small{margin:0}.notice{padding:15px 18px;border-left:3px solid var(--accent);background:#1c3040;border-radius:6px;margin-top:22px;font-size:14px}.status{min-height:28px;margin:18px 0 0;font-size:14px}.error{color:#ffbcb3}.empty{padding:40px;text-align:center;color:var(--muted)}footer{margin-top:30px;color:var(--muted);font-size:12px}[hidden]{display:none!important}@media(max-width:800px){.layout{grid-template-columns:1fr}.panel{position:static}main{padding:24px 16px 40px}header{margin-bottom:28px}.card-top{flex-wrap:wrap}}@media(prefers-reduced-motion:no-preference){button{transition:background .15s ease}}

/* One focused workspace at a time, including on a small phone. */
main{max-width:960px}.layout{display:block;margin-top:20px}.panel{position:static;max-width:640px;margin:auto}header{margin-bottom:24px;flex-wrap:wrap;gap:12px}.intro h1{font-size:clamp(28px,5vw,42px);letter-spacing:-1.3px}.intro p{margin-bottom:0}.view-nav{display:flex;gap:6px;padding:6px;margin-top:24px;background:var(--panel);border:1px solid var(--line);border-radius:14px;position:sticky;top:8px;z-index:2}.view-nav a{flex:1;text-align:center;text-decoration:none;border-radius:9px;padding:12px 8px;color:var(--muted);font-weight:750;min-height:48px}.view-nav a[aria-current=page]{background:var(--accent);color:#15200b}.status{margin:14px 0 0;min-height:0}.status:empty{display:none}.toolbar{align-items:start}.toolbar h2{font-size:23px}.watch-count{font-size:13px;display:block;font-weight:400;margin-top:4px}.cards{grid-template-columns:repeat(2,minmax(0,1fr));align-items:start}.card{min-width:0}.card h3{overflow-wrap:anywhere}.card-actions button{flex:1}.card .price{font-size:22px}.details{margin-top:14px;border-top:1px solid var(--line);padding-top:10px}summary{cursor:pointer;color:var(--muted);font-size:13px;padding:6px 0;min-height:36px}summary:focus-visible{outline:3px solid var(--accent);outline-offset:3px}.notice{margin-top:20px;font-size:12px;padding:12px 15px}.notice p{margin:0}.notice summary{font-weight:650}footer{margin-top:20px}footer p{margin-top:8px}.panel>p{font-size:14px}.empty{grid-column:1/-1;padding:28px 16px}.empty button{margin-top:12px}.form-help{margin:14px 0}.form-help small{line-height:1.6}@media(max-width:600px){main{padding:20px 16px 32px}.cards{grid-template-columns:1fr}.panel,.card{padding:18px}.intro h1{font-size:30px}.intro p{font-size:14px}.toolbar{gap:8px}.toolbar button{padding:8px 12px}.view-nav{margin-top:18px}.card-top{flex-wrap:nowrap}.pill{white-space:nowrap}.notice{margin-top:16px}header .pill{font-size:11px;padding:6px 9px}}
</style></head><body><main>
<header><div class="brand">SNIPER<span class="accent">.</span></div><span class="pill">Private watchlist</span></header>
<div class="intro"><h1>Your next record starts here.</h1><p class="muted">Your records. Your price. One place to keep watch.</p></div>
<nav class="view-nav" aria-label="Watch workspace"><a id="nav-watches" href="#watches" aria-controls="watches-view" aria-current="page">Your watches</a><a id="nav-add" href="#add" aria-controls="add-view">Add a watch</a></nav>

<p id="status" class="status" role="status" aria-live="polite">Loading your saved watches…</p>
<div class="layout"><section id="add-view" class="panel" aria-labelledby="form-title" hidden><h2 id="form-title">Add a watch</h2><p class="muted" id="form-note">Save it here. No message to your assistant needed.</p>
<form id="watch-form"><label>Discogs release link or ID<input id="release" required maxlength="500" autocomplete="off" placeholder="https://www.discogs.com/release/…"><small>Use the exact release, not a master or sell/item link. No catalog request is made.</small></label>
<label>Record name <span class="muted">(optional)</span><input id="title" maxlength="120" autocomplete="off" placeholder="Artist · album · edition"><small>Leave blank to use the release ID. This label can appear in your existing private alerts.</small></label>
<div class="row"><label>Item-price limit<input id="price" required inputmode="decimal" pattern="[0-9]{1,7}([.][0-9]{1,2})?" maxlength="10" placeholder="40.00"><small>At or below this price, before shipping and fees.</small></label><label>Currency<select id="currency"><option>USD</option><option>GBP</option><option>EUR</option><option>CAD</option><option>AUD</option></select></label></div>
<label class="check"><input id="any-price" type="checkbox">Watch availability at any price</label>
<label class="check"><input id="enabled" type="checkbox" checked>Watch active</label>
<details class="form-help"><summary>How alerts work</summary><small>New watches use the existing private alert channel when monitoring is running. Price watches report initial under-limit availability and later under-limit price drops; any-price watches report availability and count increases. Existing alert preferences are preserved.</small></details>
<div class="row form-actions"><button id="save" type="submit" disabled>Save watch</button><button id="cancel" class="secondary" type="button" hidden>Cancel edit</button></div>
</form></section>
<section id="watches-view" aria-labelledby="watches-title"><div class="toolbar"><div><h2 id="watches-title" tabindex="-1">Your watches <span id="count" class="muted watch-count"></span></h2><small id="monitor-status">Checking monitor status…</small></div><button id="refresh" type="button" class="secondary">Refresh</button></div>
<label>Find a saved watch<input id="search" type="search" placeholder="Search record name or release ID" autocomplete="off"></label><div id="watches" class="cards"></div></section></div>
<div class="notice"><p><strong>Availability leads, not verified listings.</strong> Item prices exclude shipping and fees. Nothing here purchases a record.</p><details><summary>What these watches can tell you</summary><p>These watches track the release’s aggregate lowest item price and number for sale. They cannot filter media or sleeve grade, US sellers, shipping, tax or fees.</p></details></div>
<footer><details><summary>About your watch data</summary><p>Notification counts cover retained aggregate-watch history across saved prices, not a complete lifetime delivery record. The current-settings count starts again when a watch is changed. Saved to the existing Sniper watch store. Pausing keeps the watch so you can resume it later. No credentials, payment details, or new notification destinations are configured here. Unsaved edits stay only in this page.</p></details></footer>
</main><script nonce="@@NONCE@@">
'use strict';
const el = id => document.getElementById(id);
let state = null, busy = false, locked = true, editing = null, dirty = false;
function showView(view, focus=false) { const adding=view==='add';el('add-view').hidden=!adding;el('watches-view').hidden=adding;for(const name of ['add','watches']){const link=el('nav-'+name);if(name===view)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');}document.title='Sniper · '+(adding?(editing?'Edit watch':'Add a watch'):'Your watches');if(focus){(adding?el(editing?'title':'release'):el('watches-title')).focus();window.scrollTo(0,0);} }
function navigate(view) { if(location.hash==='#'+view)showView(view,true);else location.hash=view; }
window.addEventListener('hashchange',()=>showView(location.hash==='#add'?'add':'watches',true));
function say(text, error=false) { el('status').textContent=text;el('status').classList.toggle('error',error); }
function controls() { el('save').disabled=busy||locked||!state;el('refresh').disabled=busy;el('cancel').disabled=busy;for(const node of el('watch-form').elements) { if(node.id!=='save'&&node.id!=='cancel') node.disabled=busy; }el('price').disabled=busy||el('any-price').checked;el('price').required=!el('any-price').checked;el('release').readOnly=editing!==null; for(const node of document.querySelectorAll('[data-action]')) node.disabled=busy||locked; }
async function request(path, options={}) { const response=await fetch('/watches/'+path,{credentials:'same-origin',cache:'no-store',...options});let data;try{data=await response.json();}catch{throw Error('The server response could not be verified. Refresh saved watches before trying again.');}if(!response.ok)throw Error(data.error||'The request could not be completed.');return data; }
function reset() { el('watch-form').reset();editing=null;dirty=false;el('form-title').textContent='Add a watch';el('form-note').textContent='Save it here. No message to your assistant needed.';el('save').textContent='Save watch';el('cancel').hidden=true;controls(); }
function load(w) { if(dirty&&!confirm('Replace your unsaved draft with this saved watch?'))return;editing={id:w.release_id,revision:w.revision};el('release').value=String(w.release_id);el('title').value=w.public_title;el('price').value=w.item_price_ceiling||'';el('currency').value=w.currency;el('any-price').checked=w.any_price;el('enabled').checked=w.enabled;dirty=false;el('form-title').textContent='Edit watch';el('form-note').textContent='Changes apply only to this release. To change the release, add a new watch.';el('save').textContent='Save changes';el('cancel').hidden=false;controls();navigate('add');el('title').focus(); }
function node(tag,text,cls) { const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n; }
function render() { const root=el('watches');root.replaceChildren();if(!state)return;el('count').textContent='('+state.watches.filter(w=>w.enabled).length+' active · '+state.watches.filter(w=>!w.enabled).length+' paused)';el('monitor-status').textContent=state.monitor_enabled?'Monitor enabled · latest successful checks below':'Monitor paused · saving watches will not start it';const query=el('search').value.trim().toLowerCase();const list=state.watches.filter(w=>(w.public_title+' '+w.release_id).toLowerCase().includes(query));if(!list.length){const empty=node('div',undefined,'empty');empty.append(node('p',state.watches.length?'No watches match your search.':'Your watchlist starts with one record.'));if(!state.watches.length){const add=node('button','Add your first watch');add.type='button';add.onclick=()=>navigate('add');empty.append(add);}root.append(empty);}
for(const w of list){const card=node('article',undefined,'card');const top=node('div',undefined,'card-top');const title=node('div');title.append(node('h3',w.public_title));const a=node('a','Release '+w.release_id);a.href='https://www.discogs.com/release/'+w.release_id;a.target='_blank';a.rel='noopener noreferrer';title.append(a);top.append(title,node('span',w.enabled?'Active':'Paused','pill'));card.append(top,node('p',w.any_price?'Any item price':w.currency+' '+w.item_price_ceiling+' or less','price'));const meta=node('div',undefined,'meta');const low=node('div');low.append(node('small','Latest aggregate minimum'),node('div',w.lowest_item_price?w.currency+' '+w.lowest_item_price:'Unknown'));const count=node('div');count.append(node('small','Aggregate copies for sale'),node('div',w.count===null?'Unknown':String(w.count)));meta.append(low,count);card.append(meta);const details=node('details',undefined,'details');details.append(node('summary','Check history & alert details'));const history=node('div',undefined,'meta');const notifications=node('div');notifications.append(node('small','Recorded notifications'),node('div',String(w.notifications.accepted)));const current=node('div');current.append(node('small','With current watch settings'),node('div',String(w.notifications.accepted_current_revision)));history.append(notifications,current);details.append(history);details.append(node('small','Counts are accepted by the notification service, not confirmed phone delivery.'));const pending=w.notifications.pending,flight=w.notifications.in_flight,uncertain=w.notifications.uncertain;if(pending||flight||uncertain)details.append(node('small',pending+' queued · '+flight+' in progress · '+uncertain+' uncertain (not counted above)'));const checked=w.last_success?new Date(w.last_success*1000).toLocaleString():'No successful check yet';details.append(node('small','Last successful check: '+checked));details.append(node('small','Alert preferences: '+[w.alert_initial_low?'initial availability':null,w.alert_price_drops?'price drops':null,w.alert_count_increases?'count increases':null].filter(Boolean).join(', ')));card.append(details);const actions=node('div',undefined,'card-actions');const edit=node('button','Edit','secondary');edit.type='button';edit.dataset.action='edit';edit.onclick=()=>load(w);const toggle=node('button',w.enabled?'Pause':'Resume','secondary');toggle.type='button';toggle.dataset.action='toggle';toggle.onclick=()=>save({release:String(w.release_id),title:w.public_title,currency:w.currency,price:w.item_price_ceiling,any_price:w.any_price,enabled:!w.enabled,revision:w.revision},false);actions.append(edit,toggle);card.append(actions);root.append(card);}controls(); }
async function refresh(announce=true) { if(busy)return;busy=true;controls();try{const next=await request('state');state=next;locked=false;render();if(announce)say('Saved watches refreshed. Your draft was kept.');}catch(e){locked=true;say(e.message,true);}finally{busy=false;controls();} }
async function save(fields, clearDraft) { if(busy||locked)return;busy=true;controls();say('Saving watch…');let confirmed=false;try{await request('save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...fields,csrf:state.csrf})});confirmed=true;locked=true;if(clearDraft){reset();navigate('watches');}say('Watch saved. Refreshing saved watches…');}catch(e){locked=true;say(e.message+' Your draft was kept. Refresh saved watches to check whether it saved before retrying. No automatic retry was made.',true);}finally{busy=false;controls();}if(confirmed){await refresh(false);if(locked)say('Watch saved. '+el('status').textContent,true);else say(fields.enabled?'Watch saved. The existing monitor will pick it up while enabled.':'Watch paused. You can resume it here later.');} }
el('watch-form').addEventListener('submit',event=>{event.preventDefault();const release=el('release').value.trim();const revision=editing?editing.revision:0;save({release,title:el('title').value.trim(),currency:el('currency').value,price:el('any-price').checked?null:el('price').value.trim(),any_price:el('any-price').checked,enabled:el('enabled').checked,revision},true);});
el('watch-form').addEventListener('input',()=>{dirty=true;controls();});el('any-price').addEventListener('change',controls);el('search').addEventListener('input',render);el('refresh').onclick=()=>refresh();el('cancel').onclick=()=>{if(!dirty||confirm('Discard your unsaved changes?')){reset();navigate('watches');}};window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});showView(location.hash==='#add'?'add':'watches');refresh(false);
</script></body></html>"""
